import { ImageResponse } from "next/og";

import { siteConfig } from "@/lib/site";

export const alt = `${siteConfig.name} — ${siteConfig.tagline}`;
export const size = { width: 1200, height: 630 };
export const contentType = "image/png";

/**
 * The mark, as an image.
 *
 * The social card is generated by satori, which cannot draw inline SVG. The
 * same geometry as `src/app/icon.svg` is embedded as a data URI instead, so
 * the favicon and the social preview are always the same drawing.
 */
const MARK_SVG = `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 32 32">
  <rect width="32" height="32" rx="8" fill="#1e293b"/>
  <path d="M11 8.5V19a4.5 4.5 0 0 0 4.5 4.5" fill="none" stroke="#f8fafc" stroke-width="5" stroke-linecap="round" stroke-linejoin="round"/>
  <path d="M15.5 23.5H21" fill="none" stroke="#f8fafc" stroke-opacity="0.72" stroke-width="5" stroke-linecap="round"/>
</svg>`;

const MARK = `data:image/svg+xml;base64,${Buffer.from(MARK_SVG).toString("base64")}`;

/**
 * Social preview card, generated at build time. Deliberately typographic — the
 * same restraint the app itself uses.
 *
 * The typeface is the card renderer's own sans rather than Inter: the web
 * font is a hashed build artefact, and the social card is drawn once, at
 * build time, from a drawing that has to survive without it.
 */
export default function OpenGraphImage() {
  const [lead, ...rest] = siteConfig.name.split(" ");
  const tail = rest.join(" ");

  return new ImageResponse(
    (
      <div
        style={{
          width: "100%",
          height: "100%",
          display: "flex",
          flexDirection: "column",
          justifyContent: "space-between",
          background: "#f8fafc",
          padding: "80px",
          fontFamily: "sans-serif",
        }}
      >
        <div style={{ display: "flex", alignItems: "center", gap: 20 }}>
          {/* eslint-disable-next-line @next/next/no-img-element -- satori draws plain <img>; next/image cannot be rendered inside an ImageResponse. */}
          <img src={MARK} width={72} height={72} alt="" />
          <div
            style={{
              display: "flex",
              alignItems: "baseline",
              gap: 9,
              fontSize: 34,
              color: "#1e293b",
              fontWeight: 700,
              letterSpacing: "-0.5px",
            }}
          >
            <span>{lead}</span>
            {tail ? (
              <span style={{ fontWeight: 400, color: "#64748b" }}>{tail}</span>
            ) : null}
          </div>
        </div>

        <div style={{ display: "flex", flexDirection: "column", gap: 24 }}>
          <div
            style={{
              fontSize: 68,
              lineHeight: 1.1,
              color: "#1e293b",
              fontWeight: 700,
              letterSpacing: "-1.5px",
              maxWidth: 900,
            }}
          >
            {siteConfig.tagline}
          </div>
          <div
            style={{
              fontSize: 30,
              lineHeight: 1.4,
              color: "#64748b",
              maxWidth: 900,
            }}
          >
            For schools, colleges and training teams. Classes, assignments,
            rubrics and grading — in one focused place.
          </div>
        </div>

        <div
          style={{ display: "flex", height: 8, borderRadius: 4, overflow: "hidden" }}
        >
          <div style={{ flex: 3, background: "#1e293b" }} />
          <div style={{ flex: 1, background: "#cbd5e1" }} />
          <div style={{ flex: 1, background: "#e2e8f0" }} />
        </div>
      </div>
    ),
    { ...size },
  );
}
